export const RULES: Record<string, { title: string; text: string }> = {"dict":{"title":"Слоўнікавае слова","text":"Слоўнікавае слова <b>нельга праверыць</b> — яго трэба <b>запомніць</b>. Прачытай слова па складах так, як яно пішацца."},"ak":{"title":"Аканне і яканне","text":"Літары <b>о, э</b> пішуцца толькі <b>пад націскам</b>. Без націску замест іх пішам <b>а</b>: во́ды — вада́, дрэ́ва — драўля́ны.<br>Літары <b>е, ё</b> пішуцца пад націскам. У першым складзе <b>перад націскам</b> пішам <b>я</b>: зе́млі — зямля́, вёсны — вясна́."},"uv":{"title":"Літара ў","text":"<b>ў</b> пішацца <b>пасля галоснага</b>: заўсёды, Віра ўзяла. Пасля <b>зычнага</b> пішам <b>у</b>: брат узяў. <b>ў</b> не пішацца пасля <b>знакаў прыпынку</b> і <b>не бывае вялікай</b>: Уладзік."},"zs":{"title":"Прыстаўкі з- і с-","text":"Прыстаўка пішацца так, як чуецца. Калі пасля яе <b>глухі</b> гук (к, п, т, ф, х, ц, ч, ш, с) — пішам <b>с</b>: <b>с</b>хапіла, <b>с</b>казаў. Калі <b>звонкі</b> — пішам <b>з</b>: <b>з</b>рабіў, <b>з</b>бегчы.<br><b>Увага!</b> У рускай мове інакш: там заўсёды <b>с</b> (сделал). А па-беларуску — <b>з</b>рабіў."},"dzc":{"title":"Дз і ц","text":"Перад <b>е, ё, ю, я, і, ь</b> пішам <b>дз</b> і <b>ц</b>: дзень, цётка, вецер. Перад іншымі літарамі — <b>д</b> і <b>т</b>: дом, тата, радасць."},"zac":{"title":"Зацвярдзелыя гукі","text":"Гукі <b>[р], [ж], [ш], [ч], [дж]</b> — заўсёды <b>цвёрдыя</b>. Пасля іх пішам <b>а, о, у, ы, э</b> і ніколі — я, е, ё, ю, і: рэчка, жывёла, шэсць. Цвёрды гук <b>[ц]</b> таксама: цырк."},"dvo":{"title":"Падоўжаныя зычныя","text":"Паміж <b>галоснымі</b> зычныя могуць <b>падаўжацца</b> — тады пішам <b>дзве літары</b>: жыццё, вяселле, насенне, ладдзя. Калі побач <b>няма галоснага</b>, падаўжэння няма: жыць, корань, рэчка."},"apos":{"title":"Апостраф і мяккі знак","text":"Перад <b>е, ё, ю, я, і</b> пасля <b>цвёрдага</b> зычнага пішам <b>апостраф ’</b>: сям’я, аб’ява, вераб’і. Пасля <b>мяккіх л, н, з, с, ц, дз</b> пішам <b>мяккі знак ь</b>: мільён, Ілья, вальера."},"par":{"title":"Парныя зычныя","text":"Парны зычны ў канцы слова і перад іншым зычным <b>правяраем</b>: змяняем слова так, каб пасля зычнага стаяў <b>галосны</b>: дуб — дубы, загадка — загадаць."},"err":{"title":"Правярай як настаўнік","text":"Не спяшайся. Знайдзі ў слове <b>небяспечнае месца</b> і <b>правер яго правілам</b>."},"type":{"title":"Тыпы сказаў","text":"<b>Апавядальны</b> — паведамляе, у канцы <b>кропка</b>. <b>Пытальны</b> — пытае, у канцы <b>?</b> <b>Пабуджальны</b> — просьба, загад, парада, у канцы <b>кропка або клічнік</b>. Сказ з <b>моцным пачуццём</b> — <b>клічны</b>: у канцы <b>!</b>, а ў пытальным клічным — <b>?!</b>"},"mem":{"title":"Дзейнік і выказнік","text":"1. Знайдзі <b>дзеянне</b>: што робіць? што зрабіў? — гэта <b>выказнік</b>, <b>дзве лініі</b>.<br>2. Спытай: <b>хто? што?</b> гэта робіць — гэта <b>дзейнік</b>, <b>адна лінія</b>.<br>3. Слова <b>з прыназоўнікам</b> (каля акна, на паляну) дзейнікам не бывае. Слова пасля дзеяння, якое адказвае на <b>каго? што?</b> (ловіць муху), — таксама не дзейнік."},"syn":{"title":"Сінонімы","text":"<b>Сінонімы</b> — словы з <b>аднолькавым або блізкім значэннем</b>: смелы — адважны, ісці — крочыць."},"ant":{"title":"Антонімы","text":"<b>Антонімы</b> — словы з <b>супрацьлеглым значэннем</b>: дзень — ноч, гарачы — халодны."},"fig":{"title":"Прамое і пераноснае значэнне","text":"<b>Прамое</b> значэнне — як ёсць на самой справе: калючы вожык (у яго іголкі). <b>Пераноснае</b> — падобна па нейкай прымеце: калючы вецер (як быццам коле)."},"sec":{"title":"Даданыя члены сказа","text":"Даданыя члены <b>тлумачаць</b> галоўныя ці іншыя даданыя. 1. Знайдзі <b>аснову</b>: выказнік і дзейнік. 2. Задавай <b>пытанні ад галоўных слоў</b>: які? што? каго? дзе? калі? куды? як? 3. Слова, якое адказвае на пытанне, — даданы член. Падкрэсліваем <b>пункцірам</b>. Прыназоўнік (на, у, каля) падкрэсліваем разам са словам."},"mnog":{"title":"Мнагазначныя словы","text":"У <b>мнагазначнага</b> слова <b>некалькі значэнняў</b>: ключ ад дзвярэй і ключ — крыніца. Якое значэнне — падкажуць <b>суседнія словы</b> ў сказе."},"trio":{"title":"Мнагазначныя словы","text":"Адно <b>мнагазначнае</b> слова называе розныя, але <b>чымсьці падобныя</b> прадметы: нос чалавека і нос карабля (абодва наперадзе). Падстаў слова ва ўсе тры — павінна падысці ўсюды."},"hom":{"title":"Аднолькавыя па гучанні","text":"Некаторыя словы <b>гучаць і пішуцца аднолькава</b>, але маюць <b>рознае значэнне</b>: каса (валасы) і каса (прылада). Значэнне падкажа <b>сказ</b>."},"part":{"title":"Корань і канчатак","text":"<b>Корань</b> — агульная частка роднасных слоў: <b>грыб</b>, <b>грыб</b>нік. <b>Канчатак</b> — зменная частка слова, служыць для сувязі слоў: сасн<b>а</b>, сасн<b>ы</b>, сасн<b>е</b>."},"odd":{"title":"Роднасныя словы","text":"У роднасных (аднакаранёвых) слоў <b>агульны корань і агульны сэнс</b>. Ляснік працуе ў лесе — роднаснае слова. А лесвіца да лесу не мае дачынення — лішняе."}};

